/* ============================================================================
   OG-BASE-WELCOME — Sample 1's first page, as a guest sees it.

   A faithful capture of the invitation's welcome poster: the couple
   standing on the left and the empty parchment on the right where the
   names belong. The og renderer paints the couple's own names, both
   families and the wedding date into that parchment — so the WhatsApp
   preview IS the website's first page for THAT couple, not the demo
   artwork and not a bare photograph. Embedded as a base64 PNG; one asset,
   zero fetches on the edge. */
"use strict";
const zlib = require("zlib");
const B64 = "";
let CACHE = null;
function baseImage() {
  if (CACHE) return CACHE;
  CACHE = decodePngToRgb(Buffer.from(B64, "base64"));
  return CACHE;
}
function decodePngToRgb(png) {
  let off = 8, w = 0, h = 0;
  const idat = [];
  while (off < png.length) {
    const len = png.readUInt32BE(off);
    const type = png.toString("ascii", off + 4, off + 8);
    const data = png.subarray(off + 8, off + 8 + len);
    if (type === "IHDR") { w = data.readUInt32BE(0); h = data.readUInt32BE(4); }
    else if (type === "IDAT") idat.push(data);
    else if (type === "IEND") break;
    off += 12 + len;
  }
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const stride = w * 3;
  const out = Buffer.alloc(w * h * 3);
  const line = Buffer.alloc(stride), prev = Buffer.alloc(stride);
  let p = 0;
  for (let y = 0; y < h; y++) {
    const f = raw[p++];
    raw.copy(line, 0, p, p + stride); p += stride;
    if (f === 1) for (let i = 3; i < stride; i++) line[i] = (line[i] + line[i-3]) & 255;
    else if (f === 2) for (let i = 0; i < stride; i++) line[i] = (line[i] + prev[i]) & 255;
    else if (f === 3) for (let i = 0; i < stride; i++) { const l = i>=3?line[i-3]:0; line[i] = (line[i] + ((l+prev[i])>>1)) & 255; }
    else if (f === 4) for (let i = 0; i < stride; i++) {
      const a2 = i>=3?line[i-3]:0, b2 = prev[i], c2 = i>=3?prev[i-3]:0;
      const pa = Math.abs(b2-c2), pb = Math.abs(a2-c2), pc = Math.abs(a2+b2-2*c2);
      const pr = (pa<=pb && pa<=pc)?a2:(pb<=pc?b2:c2);
      line[i] = (line[i] + pr) & 255;
    }
    line.copy(out, y*stride); line.copy(prev, 0);
  }
  return { rgb: out, w, h };
}
module.exports = { baseImage };
